with exploded as (select id, currency, explode_outer(tier_prices) as val from price_tiers), enriched as (select id, currency, val, percent_rank() over (partition by currency order by val desc) as val_percent_rank, stddev_samp(val) over (partition by currency) as currency_stddev_samp_val, sum(val) over (partition by currency) as currency_sum_val, dense_rank() over (order by val asc nulls first) as val_dense_rank, cume_dist() over (partition by currency order by val desc nulls first) as val_cume_dist from exploded), scored as (select *, dense_rank() over w_ordered as currency_stddev_samp_val_dense_rank, min(currency_stddev_samp_val) over w_recent as currency_min_currency_stddev_samp_val, cume_dist() over w_running as currency_sum_val_cume_dist, cume_dist() over w_part as val_cume_dist_2, percent_rank() over w_grp as val_cume_dist_percent_rank from enriched window w_ordered as (partition by currency order by currency_stddev_samp_val asc nulls first), w_recent as (partition by currency), w_running as (partition by currency order by currency_sum_val asc), w_part as (partition by currency order by val desc nulls last), w_grp as (order by val_cume_dist desc nulls last)), with_windows as (select id, currency, val, val_percent_rank, currency_stddev_samp_val, currency_sum_val, val_dense_rank, val_cume_dist, currency_stddev_samp_val_dense_rank, currency_min_currency_stddev_samp_val, currency_sum_val_cume_dist, val_cume_dist_2, val_cume_dist_percent_rank, cume_dist() over (order by val_cume_dist_2 desc nulls last) as val_cume_dist_2_cume_dist, max(val_cume_dist) over w_part as currency_max_val_cume_dist, sum(val_cume_dist_2) over w_part as currency_sum_val_cume_dist_2 from scored window w_part as (partition by currency)) select case when currency_sum_val_cume_dist >= 0.77 then 'HIGH' else 'LOW' end as currency_sum_val_cume_dist_tier, case when currency_sum_val >= 426 then 'HIGH' else 'LOW' end as currency_sum_val_tier, sort_array(collect_set(currency)) as currency_list, size(collect_set(currency)) as num_currencies, percentile_approx(val, array(0.25, 0.5, 0.75)) as val_quartiles, sort_array(collect_set(currency)) as currency_list_2 from with_windows group by rollup (case when currency_sum_val_cume_dist >= 0.77 then 'HIGH' else 'LOW' end, case when currency_sum_val >= 426 then 'HIGH' else 'LOW' end) having size(collect_set(currency)) > 1 order by currency_sum_val_tier desc nulls first;
